11	// Match std::stoi by consuming a signed decimal prefix and ignoring suffix characters.
12	fn parse_i32_like_stoi(input: &str) -> i32 {
13	    let trimmed = input.trim_start_matches(|ch: char| ch.is_ascii_whitespace());
14	    let bytes = trimmed.as_bytes();
15	    let mut index = 0usize;
16	    let mut negative = false;
17	
18	    if index < bytes.len() {
19	        match bytes[index] {
20	            b'+' => index += 1,
21	            b'-' => {
22	                negative = true;
23	                index += 1;
24	            }
25	            _ => {}
26	        }
27	    }
28	
29	    let digit_start = index;
30	    let mut magnitude = 0i64;
31	
32	    while index < bytes.len() && bytes[index].is_ascii_digit() {
33	        magnitude = magnitude
34	            .checked_mul(10)
35	            .and_then(|value| value.checked_add(i64::from(bytes[index] - b'0')))
36	            .unwrap_or_else(|| panic!("stoi"));
37	        index += 1;
38	    }
39	
40	    if index == digit_start {
41	        panic!("stoi");
42	    }
43	
44	    let signed = if negative { -magnitude } else { magnitude };
45	
46	    if signed < i32::MIN as i64 || signed > i32::MAX as i64 {
47	        panic!("stoi");
48	    }
49	
50	    signed as i32
51	}

